B.auI=new A.fl("Resolve the main conflict through the protagonist's action and its cost.","\u0420\u0430\u0437\u0440\u0435\u0448\u0438\u0442\u0435 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435\u043c \u0433\u0435\u0440\u043e\u044f \u0438 \u0435\u0433\u043e \u0446\u0435\u043d\u043e\u0439.","scene","climax","The confrontation","\u0420\u0435\u0448\u0430\u044e\u0449\u0430\u044f \u0432\u0441\u0442\u0440\u0435\u0447\u0430")
B.auw=new A.fl("Show the consequences and answer the central story question.","\u041f\u043e\u043a\u0430\u0436\u0438\u0442\u0435 \u043f\u043e\u0441\u043b\u0435\u0434\u0441\u0442\u0432\u0438\u044f \u0438 \u043e\u0442\u0432\u0435\u0442\u044c\u0442\u0435 \u043d\u0430 \u0433\u043b\u0430\u0432\u043d\u044b\u0439 \u0432\u043e\u043f\u0440\u043e\u0441 \u0438\u0441\u0442\u043e\u0440\u0438\u0438.","scene","aftermath","What has changed","\u0427\u0442\u043e \u0438\u0437\u043c\u0435\u043d\u0438\u043b\u043e\u0441\u044c")
